+}
+
+func (s *gitRefsStore) batchRefName(checkpointID id.CheckpointID) (plumbing.ReferenceName, error) {
+	return RefName(checkpointID)
+}
+
+func (s *GitStore) batchRepo() *git.Repository {
+	return s.repo
+}
+
