func (s *Store) writeSessionSummary(r cp.SessionSummary) error {
	sc, err := s.load(r.CheckpointID)
	if err != nil {
		return err
	}
	if sc == nil || len(sc.Sessions) == 0 {
		return fmt.Errorf("fsstore: cannot set summary for unknown checkpoint %s", r.CheckpointID)
	}
