func (s *gitRefsStore) checkpointTreeAt(commitHash plumbing.Hash, checkpointID id.CheckpointID) (*object.Tree, error) {
	if commitHash.IsZero() {
		return nil, nil //nolint:nilnil // new checkpoint ref
	}
	commit, err := s.repo.CommitObject(commitHash)
	if err != nil {
		return nil, fmt.Errorf("read checkpoint commit %s: %w", commitHash, err)
	}
	tree, err := commit.Tree()
	if err != nil {
		return nil, fmt.Errorf("read checkpoint tree for %s: %w", checkpointID, err)
	}
	return tree, nil
}

// checkpointTree resolves a FetchingTree rooted at a checkpoint's ref commit
// tree (which is the checkpoint subtree itself). Returns ErrCheckpointNotFound
// when the ref or its commit/tree cannot be resolved.
func (s *gitRefsStore) checkpointTree(ctx context.Context, cid id.CheckpointID) (*FetchingTree, error) {
	if err := ctx.Err(); err != nil {
		return nil, err //nolint:wrapcheck // Propagating context cancellation
	}
	ref, err := s.resolveRefMaybeFetch(ctx, cid)
	if err != nil {
		if errors.Is(err, plumbing.ErrReferenceNotFound) {
			return nil, ErrCheckpointNotFound
		}
		return nil, err
	}
	commit, err := s.repo.CommitObject(ref.Hash())
	if err != nil {
		// The ref resolved but its commit object doesn't — corruption/IO, not an
		// absent checkpoint. Surface it instead of masking as "not found".
		return nil, fmt.Errorf("read checkpoint commit %s for %s: %w", ref.Hash(), cid, err)
	}
	tree, err := commit.Tree()
	if err != nil {
		return nil, fmt.Errorf("read checkpoint tree for %s: %w", cid, err)
	}
	return NewFetchingTree(ctx, tree, s.repo.Storer, s.blobFetcher), nil
}

// resolveRefMaybeFetch resolves a checkpoint ref, fetching it from the remote
// once when it is missing locally and a ref fetcher is configured (the
// checkpoint may have been written on another machine). It distinguishes a
// genuinely absent ref (returns a plumbing.ErrReferenceNotFound-wrapped error,

// Package fsstore is a reference, test-only persistent checkpoint backend that
// stores checkpoints as JSON files on disk. It exists to exercise the pluggable
// backend seam (registry + mirror fan-out) with a real, non-git implementation
// of the api/checkpoint contract, and to serve as a worked example for new
// backends.
//
// It is deliberately NOT registered by production code: only a test-only helper
// (registerForTesting, in register_test.go) wires it into the checkpoint
// registry, so a production binary can never select it. As a mirror it receives
// best-effort write fan-out; it intentionally ignores
// the git-specific blob-hash fields of the contract and stores transcript bytes
// directly, which keeps the example small and makes the contract's remaining
// git leakage concrete.
//
// It is faithful to the contract's per-session metadata, batch aggregation,
// and write-request semantics — including prompt and summary redaction via the
// shared checkpoint helpers. It does not replicate derived stamps the git
// writer adds (CLI version and skill-events version); neither is needed to
// validate the pluggable seam.
