 	if err := emptyTree.Encode(obj); err != nil {
 		return fmt.Errorf("failed to encode empty tree: %w", err)
 	}
 	emptyTreeHash, err := repo.Storer.SetEncodedObject(obj)
 	if err != nil {
 		return fmt.Errorf("failed to store empty tree: %w", err)
 	}
