  tools.exec_command({"cmd":"rg -n 'func \\(s \\*ephemeralStore\\) getOrCreateShadowBranch|getOrCreateShadowBranch\\(' cmd/entire/cli/checkpoint && nl -ba cmd/entire/cli/checkpoint/ephemeral.go | sed -n '90,165p' && nl -ba cmd/entire/cli/checkpoint/shadow_ref.go | sed -n '145,175p' && nl -ba cmd/entire/cli/strategy/manual_commit_migration.go | sed -n '95,165p'","workdir":"/Users/muskanpaliwal/Work/open-source/entire/cli/improve-process-sessions-condensation","yield_time_ms":10000,"max_output_tokens":30000}),
  tools.exec_command({"cmd":"rg -n 'queued|recreat|MoveShadowBranch|move.*shadow|migration.*concurrent|Concurrent.*Migration|source.*missing' cmd/entire/cli/**/*_test.go technical.md docs/architecture/checkpoint-batch-condensation.md","workdir":"/Users/muskanpaliwal/Work/open-source/entire/cli/improve-process-sessions-condensation","yield_time_ms":10000,"max_output_tokens":30000}),
  tools.exec_command({"cmd":"nl -ba cmd/entire/cli/checkpoint/ephemeral.go | sed -n '1180,1270p' && nl -ba cmd/entire/cli/checkpoint/shadow_ref.go | sed -n '1,100p'","workdir":"/Users/muskanpaliwal/Work/open-source/entire/cli/improve-process-sessions-condensation","yield_time_ms":10000,"max_output_tokens":30000}),
  tools.exec_command({"cmd":"git show main:cmd/entire/cli/checkpoint/ephemeral.go | rg -n 'getOrCreateShadowBranch' && git show main:cmd/entire/cli/checkpoint/ephemeral.go | sed -n '1150,1240p'","workdir":"/Users/muskanpaliwal/Work/open-source/entire/cli/improve-process-sessions-condensation","yield_time_ms":10000,"max_output_tokens":30000})
]);
for (const x of results) text(x.output);

