123	// PromoteTmpRefSafely reads tmpRefName (the ref a fetch just landed into),
124	// advances destRefName to its hash via SafelyAdvanceLocalRef, then removes
125	// the tmp ref. The cleanup is deferred so the tmp ref is reaped even when
126	// the advance fails.
127	//
128	// label is a short human-readable name used in error messages. Typical use:
129	//
130	//	// fetch with refspec "+<src>:<tmpRefName>"
131	//	refs := checkpoint.ResolveRefs(ctx)
