func entireCheckpointReferences(t *testing.T, repo *git.Repository) []string {
	t.Helper()
	iter, err := repo.References()
	require.NoError(t, err)
	defer iter.Close()
	var refs []string
	require.NoError(t, iter.ForEach(func(ref *plumbing.Reference) error {
