// errStopIteration is used to stop commit iteration early in GetCheckpointAuthor.
var errStopIteration = errors.New("stop iteration")

// chunkTranscript is an indirection over agent.ChunkTranscript so tests can
// count or intercept chunking calls (e.g., to verify the short-circuit avoids
// re-chunking identical content). Production code paths always use the
// unwrapped function.
var chunkTranscript = agent.ChunkTranscript

func (s *GitStore) rootTreeHashAt(commitHash plumbing.Hash) (plumbing.Hash, error) {
	if commitHash.IsZero() {
		return plumbing.ZeroHash, nil
	}
	commit, err := s.repo.CommitObject(commitHash)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("read primary metadata commit %s: %w", commitHash, err)
	}
	return commit.TreeHash, nil
}

// subtreeObjAt returns the tree object for one checkpoint's subtree within a root
// tree, or (nil, nil) when the root or the checkpoint path does not exist yet.
// path is the in-tree checkpoint path (e.g. "a3/b2c4d5e6f7"); pass "" to return
// the root tree itself (the per-checkpoint-ref layout, where the whole tree is
// the checkpoint subtree).
func (s *treeWriter) subtreeObjAt(rootTreeHash plumbing.Hash, path string) (*object.Tree, error) {
	if rootTreeHash == plumbing.ZeroHash {
		return nil, nil //nolint:nilnil // absent checkpoint (no tree yet), not an error
	}
	rootTree, err := s.repo.TreeObject(rootTreeHash)
	if err != nil {
		if errors.Is(err, plumbing.ErrObjectNotFound) {
			return nil, nil //nolint:nilnil // tree doesn't exist yet, not an error
		}
		return nil, fmt.Errorf("failed to read root tree %s: %w", rootTreeHash, err)
	}
	if path == "" {
		return rootTree, nil
	}
	subtree, err := rootTree.Tree(path)
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // checkpoint doesn't exist yet, not an error
	}
	return subtree, nil
}

// checkpointSubtreePath joins a checkpoint-relative git tree path from a base and
// trailing segments using path.Join. Git tree paths are always "/"-separated, so
// this uses the stdlib path package (never path/filepath, which would emit "\" on
// Windows and corrupt tree keys). path.Join cleans separators, so base may be ""
// (per-checkpoint-ref root), a clean dir ("a3/b2.../0"), or a trailing-slash dir
// ("a3/b2.../"): checkpointSubtreePath("", "0", "metadata.json") == "0/metadata.json"
// and checkpointSubtreePath("a3/b2.../", "0", "metadata.json") == "a3/b2.../0/metadata.json".
// Callers therefore need not maintain the trailing-slash invariant by hand.
func checkpointSubtreePath(base string, segs ...string) string {
	if len(segs) == 0 {
		// path.Join with no segments would clean a "" base to "." — an invalid
		// git tree key. At the ref root the correct key is ""; for a non-empty
		// base, clean it to keep the trailing-slash-stripping behavior.
		if base == "" {
			return ""
		}
		return path.Clean(base)
	}
	return path.Join(append([]string{base}, segs...)...)
}

// flattenExisting flattens a checkpoint's current subtree into a path->entry map
// keyed under basePath, so the per-checkpoint write helpers (which build paths as
// basePath+"<n>/<file>") see the existing files. basePath is "" for the
// per-checkpoint-ref layout or "<shard>/<id>/" for the v1 branch layout. A nil
// subtree (new checkpoint) yields an empty map.
func (s *treeWriter) flattenExisting(existing *object.Tree, basePath string) (map[string]object.TreeEntry, error) {
	entries := make(map[string]object.TreeEntry)
	if existing == nil {
		return entries, nil
	}
	if err := FlattenTree(s.repo, existing, strings.TrimSuffix(basePath, "/"), entries); err != nil {
		return nil, err
	}
	return entries, nil
}

// buildCheckpointSubtree builds the checkpoint subtree object from entries keyed
// under basePath, stripping the prefix so the subtree is rooted at the checkpoint
// directory. With basePath "" the entries are already root-relative.
func (s *treeWriter) buildCheckpointSubtree(ctx context.Context, entries map[string]object.TreeEntry, basePath string) (plumbing.Hash, error) {
	relEntries := entries
	if basePath != "" {
		relEntries = make(map[string]object.TreeEntry, len(entries))
		for path, entry := range entries {
			relPath := strings.TrimPrefix(path, basePath)
			if relPath == path {
				continue // Entry doesn't have the expected prefix
			}
			relEntries[relPath] = entry
		}
	}
	subtree, err := BuildTreeFromEntries(ctx, s.repo, relEntries)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to build checkpoint subtree: %w", err)
	}
	return subtree, nil
}

// spliceCheckpointSubtree installs a prebuilt checkpoint subtree at the shard
// location in the v1 root tree using O(depth) tree surgery, returning the new
// root tree hash. The v1 branch always shards on the first two ID characters.
func (s *GitStore) spliceCheckpointSubtree(rootTreeHash plumbing.Hash, checkpointID id.CheckpointID, checkpointSubtree plumbing.Hash) (plumbing.Hash, error) {
	shardPrefix := string(checkpointID[:2])
	shardSuffix := string(checkpointID[2:])
	return UpdateSubtree(s.repo, rootTreeHash, []string{shardPrefix}, []object.TreeEntry{
		{Name: shardSuffix, Mode: filemode.Dir, Hash: checkpointSubtree},
	}, UpdateSubtreeOptions{MergeMode: MergeKeepExisting})
}

// applyAttributionBackfill rewrites the checkpoint root summary's combined
// attribution on the checkpoint's current subtree, returning the new subtree
// hash. Returns ErrCheckpointNotFound when the checkpoint has no root summary.
func (s *treeWriter) applyAttributionBackfill(ctx context.Context, existing *object.Tree, basePath string, combinedAttribution *Attribution) (plumbing.Hash, error) {
	entries, err := s.flattenExisting(existing, basePath)
	if err != nil {
		return plumbing.ZeroHash, err
	}

	rootMetadataPath := checkpointSubtreePath(basePath, paths.MetadataFileName)
	entry, exists := entries[rootMetadataPath]
	if !exists {
		return plumbing.ZeroHash, ErrCheckpointNotFound
	}

	summary, err := s.readSummaryFromBlob(entry.Hash)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to read checkpoint summary: %w", err)
	}
	summary.CombinedAttribution = combinedAttribution

		return plumbing.ZeroHash, stats, fmt.Errorf("store checkpoint root tree: %w", err)
	}
	return rootHash, stats, nil
}

func (s *treeWriter) readSessionMetadataFromSubtree(hash plumbing.Hash, stats *batchBuildStats) (*Metadata, error) {
	tree, err := s.repo.TreeObject(hash)
	if err != nil {
		return nil, fmt.Errorf("read session subtree: %w", err)
	}
	for _, entry := range tree.Entries {
		stats.SessionEntriesVisited++
		if entry.Name == paths.MetadataFileName && entry.Mode != filemode.Dir {
			stats.ExistingMetadataRead++
			return s.readMetadataFromBlob(entry.Hash)
		}
	}
	return nil, errors.New("metadata.json not found")
}

func (s *treeWriter) mergePreparedTasks(
	rootEntries map[string]object.TreeEntry,
	prepared map[string]plumbing.Hash,
	stats *batchBuildStats,
) (plumbing.Hash, error) {
	taskEntries := make(map[string]object.TreeEntry)
	if existing, ok := rootEntries["tasks"]; ok {
		if existing.Mode != filemode.Dir {
			return plumbing.ZeroHash, errors.New("existing tasks entry is not a directory")
		}
		tree, err := s.repo.TreeObject(existing.Hash)
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("read existing tasks tree: %w", err)
		}
		for _, entry := range tree.Entries {
			stats.TaskEntriesVisited++
			taskEntries[entry.Name] = entry
		}
	}
	for toolUseID, hash := range prepared {
		taskEntries[toolUseID] = object.TreeEntry{Name: toolUseID, Mode: filemode.Dir, Hash: hash}
	}
	return storeTreeEntryMap(s.repo, taskEntries)
}

func reduceBatchSummary(
	checkpointID id.CheckpointID,
	existing *CheckpointSummary,
	sessionPaths []SessionFilePaths,
	finalByID map[string]finalBatchSession,
	stats *batchBuildStats,
) *CheckpointSummary {
	orderedIDs := make([]string, 0, len(finalByID))
	for sessionID := range finalByID {
		orderedIDs = append(orderedIDs, sessionID)
	}
	sort.Strings(orderedIDs)

	summary := &CheckpointSummary{
		CheckpointID: checkpointID,
		CLIVersion:   versioninfo.Version,
		Sessions:     sessionPaths,
	}
	if existing != nil {
		summary.CommitSHA = existing.CommitSHA
		summary.CombinedAttribution = existing.CombinedAttribution
		summary.HasReview = existing.HasReview
		summary.HasInvestigation = existing.HasInvestigation
		summary.Imported = existing.Imported
	}
	files := make(map[string]struct{})
	for _, sessionID := range orderedIDs {
		stats.FinalSessionContributions++
		final := finalByID[sessionID]
		metadata := final.metadata
		summary.Strategy = metadata.Strategy
		summary.Branch = metadata.Branch
		if metadata.CommitSHA != "" {
			summary.CommitSHA = metadata.CommitSHA
		}
		summary.CheckpointsCount += metadata.CheckpointsCount
		summary.TokenUsage = types.AddTokenUsage(summary.TokenUsage, metadata.TokenUsage)
		summary.HasReview = summary.HasReview || final.hasReview
		summary.HasInvestigation = summary.HasInvestigation || final.hasInvestigation
		summary.Imported = summary.Imported || final.imported
		for _, file := range metadata.FilesTouched {
			files[filepath.ToSlash(file)] = struct{}{}
		}
	}
	if len(files) > 0 {
		summary.FilesTouched = make([]string, 0, len(files))
		for file := range files {
			summary.FilesTouched = append(summary.FilesTouched, file)
		}
		sort.Strings(summary.FilesTouched)
	}
	return summary
}

func finalSessionFromMetadata(metadata *Metadata) finalBatchSession {
	return finalBatchSession{
		metadata:         metadata,
		hasReview:        metadata.Kind == checkpointKindAgentReview,
		hasInvestigation: metadata.Kind == checkpointKindAgentInvestigate,
		imported:         metadata.Kind == checkpointKindImported,
	}
}

func qualifySessionFilePaths(basePath string, index int, relative SessionFilePaths) SessionFilePaths {
	qualify := func(value string) string {
		if value == "" {
			return ""
		}
		return "/" + checkpointSubtreePath(basePath, strconv.Itoa(index), strings.TrimPrefix(value, "/"))
	}
	return SessionFilePaths{
		Metadata:          qualify(relative.Metadata),
		Transcript:        qualify(relative.Transcript),
		CompactTranscript: qualify(relative.CompactTranscript),
		ContentHash:       qualify(relative.ContentHash),
		Prompt:            qualify(relative.Prompt),
		AssetsManifest:    qualify(relative.AssetsManifest),
	}
}

func storeTreeEntryMap(repo *git.Repository, entries map[string]object.TreeEntry) (plumbing.Hash, error) {
	ordered := make([]object.TreeEntry, 0, len(entries))
	for name, entry := range entries {
		entry.Name = name
		ordered = append(ordered, entry)
	}
	sortTreeEntries(ordered)
	return storeTree(repo, ordered)
}

func buildBatchCommitMessage(req BatchSessions) string {
	var message strings.Builder
	fmt.Fprintf(&message, "Checkpoint: %s\n\n", req.CheckpointID)
	if req.CommitSubject != "" {
		message.WriteString(req.CommitSubject)
		message.WriteString("\n\n")
	}
	for _, session := range req.Sessions {
		fmt.Fprintf(&message, "%s: %s\n", trailers.SessionTrailerKey, WriteOptions(session).SessionID)
	}
	if value, common := commonBatchValue(req.Sessions, func(opts WriteOptions) string { return opts.Strategy }); common {
		fmt.Fprintf(&message, "%s: %s\n", trailers.StrategyTrailerKey, value)
	}
	if value, common := commonBatchValue(req.Sessions, func(opts WriteOptions) string { return string(opts.Agent) }); common && value != "" {
		fmt.Fprintf(&message, "%s: %s\n", trailers.AgentTrailerKey, value)
	}
	if value, common := commonBatchValue(req.Sessions, func(opts WriteOptions) string { return opts.EphemeralBranch }); common && value != "" {
		fmt.Fprintf(&message, "%s: %s\n", trailers.EphemeralBranchTrailerKey, value)
	}
	return message.String()
}

func commonBatchValue(sessions []ReservedSession, value func(WriteOptions) string) (string, bool) {
	first := value(WriteOptions(sessions[0]))
	for _, session := range sessions[1:] {
		if value(WriteOptions(session)) != first {
			return "", false
		}
	}
	return first, true
}

