 // subtree (new checkpoint) yields an empty map.
 func (s *treeWriter) flattenExisting(existing *object.Tree, basePath string) (map[string]object.TreeEntry, error) {
 	entries := make(map[string]object.TreeEntry)
 	if existing == nil {
 		return entries, nil
