 116	type interruptedCondensationRecovery struct {
 117		result *CondenseResult
 118		err    error
 119		done   bool
 120	}
 121	
 122	func recoverInterruptedCondensation(
 123		ctx, logCtx context.Context,
 124		enabled bool,
 125		store cpkg.PersistentStore,
 126		state *SessionState,
 127		transcript redact.RedactedBytes,
 128		assets []cpkg.TranscriptAsset,
 129		sessionData *ExtractedSessionData,
 130		transcriptSizeBaseline int64,
 131	) interruptedCondensationRecovery {
 132		if !enabled {
 133			return interruptedCondensationRecovery{}
 134		}
 135		existingID, found, err := findInterruptedCondensation(ctx, store, state, transcript, assets)
 136		if err != nil {
 137			return interruptedCondensationRecovery{
 138				err:  fmt.Errorf("recover interrupted condensation: %w", err),
 139				done: true,
 140			}
 141		}
 142		if !found {
 143			return interruptedCondensationRecovery{}
 144		}
 145	
 146		state.PromptWindowResetPending = true
 147		logging.Info(logCtx, "recovered interrupted condensation",
 148			slog.String("session_id", state.SessionID),
 149			slog.String("checkpoint_id", existingID.String()),
 150		)
 151		return interruptedCondensationRecovery{
 152			result: &CondenseResult{
 153				CheckpointID:           existingID,
 154				SessionID:              state.SessionID,
 155				CheckpointsCount:       checkpointStepCount(state),
 156				FilesTouched:           sessionData.FilesTouched,
 157				Prompts:                sessionData.Prompts,
 158				TotalTranscriptLines:   sessionData.FullTranscriptLines,
 159				TranscriptSizeBaseline: transcriptSizeBaseline,
 160				// Set once in CondenseSession before recovery runs, so this result
 161				// carries the same probe as the normal path. Recovery is reachable
 162				// only from the non-emitting condensation paths today, but a
 163				// CondenseResult that silently drops the field is the trap
 164				// searchProbe.measured exists to catch — keep it carried.
 165				SearchProbe: sessionData.SearchProbe,
 166			},
 167			done: true,
 168		}
 169	}

