1580	// readPromptsFromFilesystem reads prompt.txt from the filesystem session metadata directory.
1581	// This file is written at turn start and updated at each SaveStep, providing prompt data
1582	// even for mid-turn commits where the shadow branch may not have been updated.
1583	func readPromptsFromFilesystem(ctx context.Context, sessionID string) []string {
1584		sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
1585		sessionDirAbs, err := paths.AbsPath(ctx, sessionDir)
1586		if err != nil {
1587			return nil
1588		}
1589		data, err := os.ReadFile(filepath.Join(sessionDirAbs, paths.PromptFileName)) //nolint:gosec // path from session ID
1590		if err != nil || len(data) == 0 {
1591			return nil
1592		}
1593		return splitPromptContent(string(data))
1594	}
1595	
1596	// clearFilesystemPrompt removes the filesystem prompt.txt for a session.
1597	// Called after condensation so subsequent checkpoints start fresh.
1598	func clearFilesystemPrompt(ctx context.Context, sessionID string) {
1599		sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
1600		sessionDirAbs, err := paths.AbsPath(ctx, sessionDir)
1601		if err != nil {
1602			return
1603		}
1604		promptPath := filepath.Join(sessionDirAbs, paths.PromptFileName)
1605		_ = os.Remove(promptPath)
1606	}
1607	
1608	func ensureCondensationAttemptID(ctx context.Context, state *SessionState) (id.CheckpointID, bool, error) {
1609		if checkpointID := state.PendingCondensationID(); checkpointID != id.EmptyCheckpointID {
1610			return checkpointID, false, nil
1611		}
1612		checkpointID, err := cpkg.GenerateCheckpointID(ctx)
1613		if err != nil {
1614			return id.EmptyCheckpointID, false, fmt.Errorf("generate checkpoint ID: %w", err)
1615		}
1616		state.BeginCondensationAttempt(checkpointID)
1617		return checkpointID, true, nil
1618	}
1619	
1620	func hasEagerCondensationContent(state *SessionState) bool {
1621		return state.StepCount > 0 || state.HasTaskContent()
1622	}
1623	
1624	// PrepareSessionEndCondensation reserves an ID for content-bearing ENDED
1625	// sessions or marks empty ENDED sessions fully condensed. File-bearing sessions
1626	// remain eligible for PostCommit.
1627	func PrepareSessionEndCondensation(ctx context.Context, state *SessionState) error {
1628		if state.Phase != session.PhaseEnded || len(state.FilesTouched) > 0 {
1629			return nil
1630		}
1631		if !hasEagerCondensationContent(state) {
1632			state.FullyCondensed = true
1633			state.ClearCondensationAttempt()
1634			return nil
1635		}
1636		_, _, err := ensureCondensationAttemptID(ctx, state)
1637		return err
1638	}
1639	
1640	func reserveDoctorCondensationAttempt(ctx context.Context, state *SessionState) (id.CheckpointID, error) {
1641		checkpointID, created, err := ensureCondensationAttemptID(ctx, state)
1642		if err != nil {
1643			return id.EmptyCheckpointID, err
1644		}
1645		if created && state.Phase == session.PhaseEnded && len(state.FilesTouched) == 0 {
1646			state.RequireCondensationRecovery()
1647		}
1648		return checkpointID, nil
1649	}
1650	
1651	// CondenseSessionByID condenses a session by its ID and cleans up.
1652	// This is used by "entire doctor" to salvage stuck sessions.
1653	func (s *ManualCommitStrategy) CondenseSessionByID(ctx context.Context, sessionID string) error {
1654		logCtx := logging.WithComponent(ctx, "condense-by-id")
1655	
1656		repo, err := OpenRepository(ctx)
1657		if err != nil {
1658			return fmt.Errorf("failed to open repository: %w", err)
1659		}
1660		defer repo.Close()
1661	
1662		var checkpointID id.CheckpointID
1663		reserveErr := MutateSessionState(ctx, sessionID, func(state *SessionState) error {
1664			var reserveErr error
1665			checkpointID, reserveErr = reserveDoctorCondensationAttempt(ctx, state)
1666			return reserveErr
1667		})
1668		if errors.Is(reserveErr, ErrStateNotFound) {
1669			return fmt.Errorf("session not found: %s", sessionID)
1670		}
1671		if reserveErr != nil {
1672			return fmt.Errorf("failed to reserve checkpoint ID: %w", reserveErr)
1673		}
1674	
1675		var shadowBranchName string
1676		var clearAfter bool
1677		var newSkillEvents []agent.SkillEvent
1678		mutErr := MutateSessionStateOnSaved(ctx, sessionID, func(state *SessionState) error {
1679			if state.PendingCondensationID() != checkpointID {
1680				return ErrMutationSkip
1681			}
1682	
1683			shadowBranchName = getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
1684			refName := plumbing.NewBranchReferenceName(shadowBranchName)
1685			_, refErr := repo.Reference(refName, true)
1790		return shadowBranchName, true, nil
1791	}
1792	
1793	// CondenseAndMarkFullyCondensed condenses an ENDED session and marks it
1794	// FullyCondensed in one operation. Used by the session stop hook to eagerly
1795	// clean up sessions so PostCommit doesn't have to process them.
1796	//
1797	// This does NOT call CondenseSessionByID because that method has two behaviors
1798	// we don't want: (1) it calls clearSessionState when no shadow branch exists
1799	// (deletes the state file entirely), and (2) it sets Phase = IDLE. Instead,
1800	// we inline the condensation logic with ENDED-appropriate behavior.
1801	//
