1600	// backfillSummary updates the summary field in the requested session's metadata.
1601	// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
1602	func (s *GitStore) backfillSummary(ctx context.Context, req SessionSummary) error {
1603		if err := ctx.Err(); err != nil {
1604			return err //nolint:wrapcheck // Propagating context cancellation
1605		}
1606	
1607		// Backfills require the branch to exist; a miss must not create it.
1608		if err := s.requireSessionsBranch(); err != nil {
1609			return err
1610		}
1611	
1612		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
1613		targetSessionID := req.SessionID
1614		_, err := RunRefTransaction(ctx, s.repo, s.refs.Primary, func(parentHash plumbing.Hash) (plumbing.Hash, bool, error) {
1615			if parentHash.IsZero() {
1616				return plumbing.ZeroHash, false, ErrCheckpointNotFound
1617			}
1618			rootTreeHash, err := s.rootTreeHashAt(parentHash)
1619			if err != nil {
1620				return plumbing.ZeroHash, false, err
1621			}
1622			existing, err := s.subtreeObjAt(rootTreeHash, req.CheckpointID.Path())
1623			if err != nil {
1624				return plumbing.ZeroHash, false, err
1625			}
1626			checkpointSubtree, sessionID, err := s.applySummaryBackfill(ctx, existing, req.CheckpointID.Path()+"/", targetSessionID, req.Summary)
1627			if err != nil {
1628				return plumbing.ZeroHash, false, err
1629			}
1630			if targetSessionID == "" {
1631				targetSessionID = sessionID
1632			}
1633			newTreeHash, err := s.spliceCheckpointSubtree(rootTreeHash, req.CheckpointID, checkpointSubtree)
1634			if err != nil {
1635				return plumbing.ZeroHash, false, err
1636			}
1637			commitMsg := fmt.Sprintf("Update summary for checkpoint %s (session: %s)", req.CheckpointID, sessionID)
1638			newCommitHash, err := CreateCommit(ctx, s.repo, newTreeHash, parentHash, commitMsg, authorName, authorEmail)
1639			return newCommitHash, true, err
1640		})
1641		return err
1642	}
1643	
1644	// backfillTranscript replaces the transcript, prompts, and context for an existing
1645	// committed checkpoint. Uses replace semantics: the full session transcript is
1646	// written, replacing whatever was stored at initial condensation time.
1647	//
1648	// This is called at stop time to finalize all checkpoints from the current turn
1649	// with the complete session transcript (from prompt to stop event).
1650	//

