	testutil.RunGit(t, dir, "branch", oldShadowBranch, oldBaseCommit)
	testutil.RunGit(t, dir, "branch", newShadowBranch, newBaseCommit)

	repo, err := OpenRepository(t.Context())
	require.NoError(t, err)
